import { AppContext } from "approot/global/services/context";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";
import SearchSource from "approot/global/searchSource";
import { UnderscoreStatic } from "underscore";
import { ParentPayRepository } from "../../parentpay.repository";
import { NamedEntityDto } from "approot/global/models/common.model";
import * as parentPayRefs from "../../parentpay.refs";

declare var _: UnderscoreStatic;
declare var extDeferred: any;

export class SetStudentLinkController extends NetCityModalController{
	public header: string;
	public student: NamedEntityDto;
	public search: SearchSource;
	public searchSettings: any;

	/*@ngInject*/
	constructor(
		$http: any,
		$scope: any,
		public $dialogs: DialogsService,
		private $alerts: AlertsService,
		public language: any,
		appContext: AppContext,
		public $uibModalInstance,
		changeTracker,
		private payments: any,
		private parentPayRepository: ParentPayRepository,
		private $q
	) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);
		let searchSettings = {
			students: {
				url: "/webapi/users/search",
				params: {
					schoolId: () => appContext.schoolId,
					student: () => true,
					take: 100,
					contains: true
				}
			}
		};
		this.header = "Привязка воспитанников";
		this.search = new SearchSource(searchSettings, $http);
	}

	saveProcess(): void {
		$(document).trigger("showProcessing");
		this.parentPayRepository.setStudentLink(this.student.id, this.payments.map(x => x.id)).then(() => {
			this.$uibModalInstance.close();
			this.$alerts.success(this.language.Generic.Common.kDataSaved);
		});
	}

	save(): void {
		var notValidMessage = this.notValid();
		if (notValidMessage) {
			this.$dialogs.message(notValidMessage);
		} else {
			$(document).trigger("showProcessing");
			var confirms = [];
			var confirmFunc = (confirmMessages) => {
				 if (confirmMessages && confirmMessages.length) {
					 confirmMessages.forEach(confirmMessage =>
						 confirms.push(() => this.$dialogs.confirm(confirmMessage)));
				 }
			}
			this.$q.all([
				this.confirmDifferentAccountNumbers().then(confirmFunc),
				this.confirmDifferentStudentAccount().then(confirmFunc),
				this.confirmCheckStudentLink().then(confirmFunc)
			]).then(() => {
				$(document).trigger("closeProcessing");
				if (confirms.length) {
					extDeferred.when(confirms).then(() => {
						this.saveProcess();
					});
				} else {
					this.saveProcess();
				}
			});
		}
	}

	notValid(): string {
		if (!this.payments) {
			return "Пустой список платежей";
		}
		if (!this.student) {
			return "Выберите воспитанника";
		}
		return "";
	}

	confirmDifferentAccountNumbers(): Promise<string[]> {
		return new Promise((resolve) => {
			if (_.keys(_.groupBy(this.payments, "accountNumber")).length > 1) {
				resolve(["Внимание! Значения поля \"№ лицевого счета\" у выбранных платежей различаются.\nВы желаете продолжить?"]);
			};
			resolve([]);
		});
	}

	confirmDifferentStudentAccount(): Promise<string[]> {
		return this.parentPayRepository.getParamValue(this.student.id, parentPayRefs.UserParams.accountNumber).then(
			(accountNumber) => {
				if (!accountNumber || !accountNumber.length) {
					return [];
				}
				let payments = _.filter(this.payments, (item) => { return (item as any).accountNumber && (item as any).accountNumber != accountNumber[0].text });
				if (!payments || !payments.length) {
					return [];
				}
				var result = payments.map((payment) => `Номер лицевого счета у воспитанника (${accountNumber[0].text}) отличается от номера в платежной ведомости (${(payment as any).accountNumber}).\nВы желаете продолжить?`);
				return result;
			});
	}

	confirmCheckStudentLink(): Promise<string[]> {
		return this.parentPayRepository.getStudentLinks(this.payments.map(x => x.id)).then(
			(links) => {
				if (!links) {
					return [];
				}
				var errorLinks = links.filter(link => { return link.students != null && link.students.length });
				if (!errorLinks.length) {
					return [];
				}
				var result = errorLinks.map((link) => `Выбранный платеж уже привязан с воспитанником ${link.students.map(student => student.name + " (" + student.currentClassInfo + ")").join(", ")}.\nВ случае продолжения платеж будет привязан с ${this.student.name}.\n${link.payDate}, ${link.payNumber}, ${link.payInfo}\nВы желаете продолжить?`)
				return result;
			});
	}
}

export const SetStudentLinkComponent = {
	controller: SetStudentLinkController,
	templateUrl: "/static/dist/app/school/parentpay/payrecords/registry/setStudentLink.component.html"
}




