import { IFilterPanel, FilterPanelSettings } from "approot/global/components/filterpanel/filterpanel.model";
import { PageContext, AppContext } from "approot/global/services/context";
import * as Rights from "approot/global/references/rights.js";
import { AppLoader } from "approot/global/apploader";
import { LongWorkService, DialogsService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { ChangeTracker } from "approot/global/changeTracker";
import { ParentPayRepository } from "../parentpay.repository";
import { StudentMonthParentPayDto, PayNormDto, ParentPayAttendanceDto, StudentParentPayInfo, StudentParentsInfo } from "../parentpay.model";
import { NamedEntityDto } from "approot/global/models/common.model";

const fEpsilon = 0.00001;

class EditParentPayController {
	private selfOnly: boolean;
	private readOnly: boolean;
	private classIds: number[];

	public filterPanel: IFilterPanel;
	public filterPanelSettings: FilterPanelSettings;

	private classId: number;
	private year: number;
	private month: number;
	public outDebtsMode: boolean;

	public maxAttendance: number;
	public parentPayForm: ng.IFormController;

	public payNorms: PayNormDto[];
	public studentMonthPays: StudentMonthParentPay[];

	private initDebts: { [studentId: number]: number } = {};
	private studentsParents: StudentParentsInfo[] = [];

	/*@ngInject*/
	constructor(
		appContext: AppContext,
		private $scope: ng.IScope,
		public language: any,
		private $location: ng.ILocationService,
		private pageContext: PageContext,
		private $dialogs: DialogsService,
		private $appLoader: AppLoader,
		private $longWork: LongWorkService,
		private $alerts: AlertsService,
		private changeTracker: ChangeTracker,
		private parentPayRepository: ParentPayRepository,
	) {
		this.readOnly = !appContext.hasAnyRight([Rights.arJournalEditAll]);
		this.selfOnly = appContext.hasAnyRight([Rights.arJournalEditSelf]) && this.readOnly;

		this.pageContext.title = language.Generic.Grade.kParentPayForMonth;
		this.pageContext.parent = {
			title: "Родительская плата",
			href: "/asp/Grade/ParentPay.asp",
			postTo: true
		};

		this.pageContext.back = null;
		let fpValues = null;

		let params = $location.search();
		if (params && params.classId && params.monthId) {
			fpValues = {
				PCLID: params.classId,
				MonthsFilter: params.monthId
			}
		}

		if (this.selfOnly) {
			parentPayRepository.getClassIdsIdForClassChief(appContext.userId)
				.then((classIds) => {
					this.classIds = classIds;
					this.checkReadOnly(params.classId)
				});
		}

		this.filterPanelSettings = {
			url: this.parentPayRepository.filterpanelUrl,
			sources: null,
			values: fpValues,
			events: {
				ready: (values) => {
					this.classId = values.PCLID;
					if (this.selfOnly)
						this.checkReadOnly(this.classId)
					this.outDebtsMode = this.classId == -1;

					let monthId = <string>values.MonthsFilter;

					this.$location.search({
						classId: this.classId,
						monthId: monthId
					})

					this.year = parseInt(monthId.split("_")[0]);
					this.month = parseInt(monthId.split("_")[1]);
					this.load();
				},
				canChange: () => {
					return new Promise((resolve) => {
						this.changeTracker.check().then(() => resolve(true), () => resolve(false));
					})
				}

			}
		}
	}

	checkReadOnly(classId: number) {
		if (this.classIds.indexOf(Number(classId)) > -1)
			this.readOnly = false;
		else
			this.readOnly = true;
	}

	onChange(studentMonthPays: StudentMonthParentPay) {
		studentMonthPays.reCalc(this.payNorms);
		this.changeTracker.dataWasChanged();
	}

	save() {
		if (this.parentPayForm.$invalid || !this.changeTracker.isDataChanged()) {

			if (this.parentPayForm.$error.required) {
				this.$dialogs.message(this.language.Generic.Grade.kErr_AttendCount_Without_Norm);
				return;
			}

			if (this.parentPayForm.$error.minmax) {
				this.$dialogs.message(this.language.Generic.Grade.kErr_AttendCount + " " + this.maxAttendance + " " + this.language.Generic.Grade.kOrMakeFieldEmpty);
				return;
			}

			if (this.parentPayForm.$error.daysCountOverflow) {
				this.$dialogs.message(this.language.Generic.Grade.kErr_AttendCountSumm + " " + this.maxAttendance);
				return;
			}
			return;
		}

		let saveData: StudentMonthParentPayDto[] = this.studentMonthPays
			.filter(sm => sm.isFilled)
			.map((sm: StudentMonthParentPay) => sm.saveData);

		let processing = this.$longWork.show();
		this.parentPayRepository.saveMonthParentPay(this.classId, this.year, this.month, saveData)
			.then(() => {
				this.changeTracker.clearDataChanges();
				this.$alerts.success("Родительская плата успешно сохранена");
				return this.load()
			})
			.then(() => {
				processing.close();
			})
	}


	public get emptyData() {
		return !this.studentMonthPays || this.studentMonthPays.length == 0;
	}

	load() {
		if (!this.$appLoader.displayed) {
			this.$longWork.show();
		}
		let students: StudentParentPayInfo[];
		let pays: StudentMonthParentPayDto[];

		let endDate = new Date(this.year, this.month, 0);
		let monthDaysCount = endDate.getDate();
		this.maxAttendance = monthDaysCount;

		let preparePayNorms = this.parentPayRepository.getPayNorms(this.year, this.month)
			.then(res => this.payNorms = res);

		let prepareStudentList = this.parentPayRepository.getStudentParentPayInfo(this.classId, this.year, this.month)
			.then(studentsDto => {
				students = studentsDto
			});

		let prepareInitDebts = () => {
			return new Promise((resolve) => {
				let studentIds = students.map(s => s.studentId);
				let newStudent = studentIds.find(sid => typeof (this.initDebts[sid]) === "undefined");
				if (newStudent) {
					return this.parentPayRepository.getInitDebts(studentIds)
						.then(res => {
							this.initDebts = res
							students.forEach(st => this.initDebts[st.studentId] = this.initDebts[st.studentId] || 0)
						})
						.then(() => resolve())
				}
				resolve()
			})
		}

		let prepareStudentParents = () => {
			return new Promise((resolve) => {
				let studentIds = students.map(s => s.studentId);
				let newStudent = studentIds.find(sid => this.studentsParents.findIndex(sp => sp.studentId == sid) == -1);

				if (newStudent) {
					return this.parentPayRepository.getStudentParents(studentIds)
						.then(res => {
							this.studentsParents = res

							students.forEach(st => {
								if (this.studentsParents.findIndex(sp => sp.studentId == st.studentId) != -1) {
									return;
								}
								this.studentsParents.push({ studentId: st.studentId, parents: [] });
							})


						})
						.then(() => resolve())
				}
				resolve()
			})
		}

		let prepareMonthPays = this.parentPayRepository.getMonthParentPay(this.classId, this.year, this.month)
			.then((paysDto) => pays = paysDto);


		return Promise.all([prepareMonthPays, prepareStudentList, preparePayNorms])
			.then(() => prepareInitDebts())
			.then(() => prepareStudentParents())
			.then(() => {
				this.changeTracker.clearDataChanges();

				this.studentMonthPays = students.map(st => {
					let parents = this.studentsParents.find(sp => sp.studentId == st.studentId).parents;
					let payInfo = pays.find(p => p.studentId == st.studentId);
					let debt = this.initDebts[st.studentId];

					return new StudentMonthParentPay(st, parents, payInfo, debt);
				})

				this.studentMonthPays.forEach(s => s.reCalc(this.payNorms));

				if (!this.$appLoader.displayed) {
					this.$longWork.close();
				}
				this.$scope.$applyAsync();
				this.$appLoader.hide();
			});
	}

	public isAttendanceMismatch(studentPayInfo: StudentMonthParentPay) {
		let payAttendance = studentPayInfo.attendance
			.filter(att => {
				let payNorm = this.payNorms.find(p => p.id == att.normId);
				return payNorm && !payNorm.noAttendance;
			})
			.reduce((sum, att) => sum + att.attendance, 0);

		return payAttendance > 0 && payAttendance != studentPayInfo.info.presentAttendance;
	}
}

class StudentMonthParentPay implements StudentMonthParentPayDto {
	payId: number;
	studentId: number;

	attendance: ParentPayAttendanceDto[];

	compensation: number;
	debt: number;
	content: number;
	correction: number;
	toPay: number;
	payVal: number;
	parentId?: number;

	prevDebt?: number;

	constructor(
		public info: StudentParentPayInfo,
		public parents: NamedEntityDto[],
		payInfo?: StudentMonthParentPayDto,
		initDebt?: number
	) {
		if (payInfo) {
			this.payId = payInfo.payId;
			this.debt = payInfo.debt;
			this.content = payInfo.content;
			this.compensation = payInfo.compensation;
			this.toPay = payInfo.toPay;
			this.correction = payInfo.correction;
			this.payVal = payInfo.payVal;
			this.attendance = payInfo.attendance;
			this.parentId = payInfo.parentId;
		}
		this.studentId = info.studentId;
		this.attendance = this.attendance || [];
		if (this.attendance.length == 0 && !this.info.readOnly) {
			this.attendance.push({
				attendance: null,
				normId: info.payNormId,
				numOrder: 1
			})
		}

		if (typeof (info.prevDebt) == "undefined" || info.prevDebt == null) {
			this.prevDebt = initDebt || 0;
		}
		else {
			this.prevDebt = info.prevDebt;
		}
	}

	public reCalc(payNorms: PayNormDto[]) {
		let useNorm: PayNormDto;
		let maxAtt = 0;
		let toPay = 0;

		for (const attendanceInfo of this.attendance) {
			let payNorm = payNorms.find(p => p.id == attendanceInfo.normId);
			if (!payNorm) {
				continue;
			}
			toPay += payNorm.normValue * attendanceInfo.attendance;
			//вычисление "основного" норматива расчета
			if (!payNorm.noAttendance && attendanceInfo.attendance >= maxAtt) {
				useNorm = payNorm;
				maxAtt = attendanceInfo.attendance;
			}
		}

		this.toPay = Number(toPay.toFixed(2));
		this.debt = (this.prevDebt || 0) + (this.payVal || 0) - this.toPay;
		this.content = this.calcContent();
		this.compensation = this.calcCompens(useNorm);
	}

	public calcContent() {
		var content = 0;

		if ((this.payVal + this.prevDebt) > (this.toPay + fEpsilon))
			if (this.prevDebt > fEpsilon)
				content = this.toPay;
			else
				content = this.toPay - this.prevDebt;
		else
			if (this.prevDebt > fEpsilon)
				content = this.payVal + this.prevDebt;
			else
				content = this.payVal;

		return content;
	}

	public calcCompens(payNorm: PayNormDto) {
		var compens = 0;
		if (!payNorm) {
			return compens;
		}
		if ((this.content > fEpsilon) && (payNorm.normValue > fEpsilon) && (payNorm.avgValue > fEpsilon))
			compens = this.content * payNorm.avgValue / payNorm.normValue;

		return compens;
	}

	public get isFilled() {
		return this.payId || this.toPay || this.correction || this.content || this.payVal || this.attendance.findIndex(a => a.attendance >= 0 && a.normId > 0) > -1;
	}

	public get saveData(): StudentMonthParentPayDto {
		return {
			studentId: this.studentId,
			content: this.content,
			compensation: this.compensation,
			debt: this.debt,
			payId: this.payId,
			toPay: this.toPay,
			payVal: this.payVal,
			parentId: this.parentId,
			correction: this.correction,
			attendance: this.attendance
				.filter(a => a.attendance >= 0 && a.normId)
				.map(a => Object.assign({}, a)),
		}
	}

	public get parentFio() {
		return this.parentId? this.parents.find(p => p.id == this.parentId).name : "";
	}
}


export const EditParentPayComponent = {
	controller: EditParentPayController,
	reloadOnSearch: false,
	controllerAs: "$ctrl",
	templateUrl: "/static/dist/app/school/parentpay/edit/editparentpay.component.html"
}



