declare var angular: any;

const module = angular.module("irtech.netcity.school.parentpay",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

import { ParentPayRepository } from "./parentpay.repository";
import { SchoolParentPayRegistryComponent } from "./payrecords/registry/schoolParentPay.component";
import { EditParentPayComponent } from "./edit/editparentpay.component";
import { NumericModelDirective } from "approot/school/calendar/curriculum/plan/floatinput.directive";
import { ParentPayAttendanceComponent, AttendanceListInputDirective } from "./edit/parentpay.attendance.component";

module
	.service("parentPayRepository", ParentPayRepository)
	.directive("numericInput", NumericModelDirective)
	.directive(AttendanceListInputDirective.selector, AttendanceListInputDirective)
	.component(ParentPayAttendanceComponent.selector, ParentPayAttendanceComponent)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/edit/", EditParentPayComponent)
			.when("/payrecords/registry/", SchoolParentPayRegistryComponent)
			.otherwise(SchoolParentPayRegistryComponent);
		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



