import { ParentPayAttendanceDto, PayNormDto } from "../parentpay.model";
import { NumericInputDirectiveLink } from "approot/school/calendar/curriculum/plan/floatinput.directive";

class ParentPayAttendanceController {
	public maxAttendance: number;
	public payNorms: PayNormDto[];
	public attendance: ParentPayAttendanceDto[];
	public readOnly: boolean;

	public form: ng.IFormController;
	public forms: ng.IFormController[] = [];

	public onChange: () => void;

	addNorm() {
		let attendance: ParentPayAttendanceDto = {
			attendance: null,
			normId: null,
			numOrder: 1
		}
		this.attendance.push(attendance);
	}

	getAttendancePayNormName(att: ParentPayAttendanceDto) {
		let payNorm = this.payNorms.find(p => p.id == att.normId);
		if (!payNorm) {
			return "";
		}
		return this.getPayNormName(payNorm)
	}

	getPayNormName(payNorm: PayNormDto) {
		return payNorm.abbrev + ' (' + payNorm.normValue + '/' + payNorm.avgValue + ')';
	}


}

/*@ngInject*/
export const AttendanceListInputDirective = ($timeout: ng.ITimeoutService) => {
	return {
		require: 'ngModel',
		link: function (scope, element, attr, ngModel: ng.INgModelController) {
			NumericInputDirectiveLink(scope, element, attr, ngModel);

			let controlName = attr["name"];

			let attendanceController = scope.$parent.$parent.$ctrl as ParentPayAttendanceController;
			let ngModels = attendanceController.forms.map(f => f[controlName] as ng.INgModelController);

			let totalDays = parseInt(attr["max"]);

			ngModel.$validators.daysCountOverflow = () => {


				let sumAttendance = ngModels.reduce((sum, ngm) => sum + ( ngm && (<any>ngm).$$rawModelValue || 0), 0);
				let valid = (sumAttendance <= totalDays);

				ngModels.forEach(ngm => ngm && ngm.$setValidity("daysCountOverflow", valid));

				return valid;
			};
		}
	}
}
AttendanceListInputDirective.selector = "attendanceListInput";

export const ParentPayAttendanceComponent = {
	selector: "parentPayAttendance",
	controller: ParentPayAttendanceController,
	controllerAs: "$ctrl",
	bindings: {
		attendance: "=",
		maxAttendance: "<",
		payNorms: "<",
		onChange: "&",
		readOnly: "<"
	},
	template: `
		<div class="parentpay-attendance" ng-form="$ctrl.form">
		<div class="attendance-list">
			<div ng-repeat="payAttendance in $ctrl.attendance" class="attendance-block" ng-form="$ctrl.forms[$index]">
				<div class="attendance" ng-class="{'has-error': $ctrl.forms[$index].attendance.$invalid}">
					<input ng-if="!$ctrl.readOnly" attendance-list-input name="attendance" class="form-control" type="text" size="1" maxlength="2" max="{{$ctrl.maxAttendance}}" ng-model="payAttendance.attendance" ng-change="$ctrl.onChange()">
					<input ng-if="$ctrl.readOnly" name="attendance" disabled class="form-control" type="text" size="1" maxlength="2" ng-value="payAttendance.attendance">
				</div>
				<div class="paynorm" ng-class="{'has-error': $ctrl.forms[$index].paynorm.$invalid}">
					<select ng-if="!$ctrl.readOnly" name="paynorm" class="form-control" ng-required="payAttendance.attendance" ng-options="payNorm.id as $ctrl.getPayNormName(payNorm) for payNorm in $ctrl.payNorms" ng-model="payAttendance.normId" ng-change="$ctrl.onChange()">
						<option value=""></option>
					</select>
					<input ng-if="$ctrl.readOnly" disabled class="form-control" type="text" ng-value="$ctrl.getAttendancePayNormName(payAttendance)">
				</div>
			</div>
		</div>
		<div class="action-panel" ng-if="!$ctrl.readOnly">
			<a href="javascript:void(0)" ng-click="$ctrl.addNorm()" title="Добавить норматив" style="text-decoration:none;">
				<i class="icon-plus"></i>
			</a>
		</div>
		</div>
	`
}


