import { IRegistryController, RegistryBtn, SelectionMode, RegistryInfo } from "approot/global/components/registry/registry.model";
import { PageContext } from "approot/global/services/context";
import { DialogsService } from "approot/global/providers/uikit.dialogs";
import { AlertsService } from "approot/global/providers/uikit.alerts";
import { ParentPayRepository } from "../../parentpay.repository";
import { CurrencyDecorator } from "approot/em/parentpay/payrecords/registry/parentpayRegistry.component";
import { SetStudentLinkComponent } from "./setStudentLink.component";

export class SchoolParentpayRegistryController {
	public controller: IRegistryController;
	public registryInfo: RegistryInfo;
	
	/*@ngInject*/
	constructor(
		pageContext: PageContext,
		private $dialogs: DialogsService,
		private $uibModal: ng.ui.bootstrap.IModalService,
		private $alerts: AlertsService,
		public language: any,
		private parentPayRepository: ParentPayRepository
	) {
		pageContext.title = language.Generic.MenuFolders.kParentPayPayments;
		pageContext.parent = null;

		const setStudentLinkButton: RegistryBtn = {
			title: "Указать воспитанника",
			icon: "glyphicon glyphicon-link",
			selectionMode: SelectionMode.Multiple,
			action: () => {
				this.setStudentLink();
			}
		};

		const clearStudentLinkButton: RegistryBtn = {
			title: "Удалить привязку",
			icon: "glyphicon glyphicon-remove",
			selectionMode: SelectionMode.Single,
			action: () => {
				this.clearStudentLink();
			}
		};

		this.registryInfo = {
			url: "/webapi/school/parentpay/payrecords/registry",
			filtersUrl: "/webapi/school/parentpay/payrecords/registry/filter",
			linkButtons: [],
			fieldDecorators: {
				pay: new CurrencyDecorator()
			},
			buttons: [setStudentLinkButton, clearStudentLinkButton],
		}
	}

	setStudentLink() {
		let selected = this.controller.selection.selected;

		const modalInstance = this.$uibModal.open({
			templateUrl: SetStudentLinkComponent.templateUrl,
			controller: SetStudentLinkComponent.controller,
			controllerAs: "$ctrl",
			size: "lg",
			resolve: {
				payments: () => selected
			}
		});

		modalInstance.result.then(() => {
			this.controller.load();
		});
	}

	isHighlighted(row) {
		return !row.childFio;
	}

	clearStudentLink() {
		let selected = this.controller.selection.selected;
		this.$dialogs.confirm("Удалить привязку воспитанника?").then(() => {
			this.parentPayRepository.clearStudentLink(selected[0].id).then(() => {
				this.$alerts.success(this.language.Generic.Common.kDataSaved);
				this.controller.load();
			});

		});
	}
}

export const SchoolParentPayRegistryComponent = {
	template: `<registry info="$ctrl.registryInfo" controller="$ctrl.controller"></registry>`,
	controller: SchoolParentpayRegistryController,
	controllerAs: "$ctrl"
}



