"use strict";

import { BaseRepository } from "approot/global/repository/baseRepository";
import { StudentMonthParentPayDto, PayNormDto, StudentParentPayInfo, StudentParentsInfo } from "./parentpay.model";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { AppContext } from "approot/global/services/context";

export class ParentPayRepository extends BaseRepository {

	/*@ngInject*/
	constructor($http, $dialogs: DialogsService, $longWork: LongWorkService, private appContext: AppContext) {
		super($http, $dialogs, $longWork)
	}

	filterpanelUrl = "/webapi/parentpay/filter";

	getStudentLinks(paymentIds: number[]) {
		return this.$http.get("/webapi/school/parentpay/payrecords/getStudentLinks", { params: { paymentId: paymentIds } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	setStudentLink(studentId: number, paymentIds: number[]) {
		return this.$http.post("/webapi/school/parentpay/payrecords/students", paymentIds, { params: { studentId: studentId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	clearStudentLink(paymentId: number) {
		return this.$http.delete("/webapi/school/parentpay/payrecords/students", { params: { paymentId: paymentId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getParamValue(userId: number, paramId: number) {
		return this.$http.get("/webapi/userinfo/parameter/value", { params: { userId: userId, paramId: paramId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getMonthParentPay(classId: number, year: number, month: number): Promise<StudentMonthParentPayDto[]> {
		let params = { classId: classId, year: year, month: month };
		return this.$http.get("/webapi/parentpay/", { params: params })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	saveMonthParentPay(classId: number, year: number, month: number, data: StudentMonthParentPayDto[]): Promise<void> {
		let params = { classId: classId, year: year, month: month };
		return this.$http.post("/webapi/parentpay/", data, { params: params })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getPayNorms(year: number, month: number): Promise<PayNormDto[]> {
		let params = { year: year, month: month, schoolId: this.appContext.schoolId };
		return this.$http.get("/webapi/parentpay/paynorms", { params: params })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getStudentParentPayInfo(classId: number, year: number, month: number): Promise<StudentParentPayInfo[]> {
		let params = { classId: classId, year: year, month: month };
		return this.$http.get("/webapi/parentpay/students", { params: params })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getInitDebts(studentIds: number[]): Promise<{ [studentId: number]: number }> {
		return this.$http.post("/webapi/parentpay/debts", { studentId: studentIds })
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getStudentParents(studentIds: number[]): Promise<StudentParentsInfo[]> {
		return this.$http.get("/webapi/parentpay/studentparents", { params: { studentId: studentIds } })
			.then(this.handleResponse)
			.catch(this.handleError);

	}

	getClassIdsIdForClassChief(userId: number): Promise<number[]> {
		return this.$http.get("/webapi/parentpay/classIds", { params: { userId: userId } })
			.then(this.handleResponse)
			.catch(this.handleError);
	}
}


